Input.flush_buffered_events()
var dlg = get_node("/root/Spine/Ui/UiRoot/DialogLayer/database")
var e = dlg.find_children("content-*", "Button", true, false)
var tabs = dlg.find_children("tab-*", "Button", true, false)
return {"entries": e.size(), "checked": str(tabs.filter(func(b): return b.button_pressed).map(func(b): return str(b.name)))}

